def check_sequence(g1, g2, g3, length=2025):
    g = [0] * (length + 1)
    g[1] = g1
    g[2] = g2
    g[3] = g3

    # g(1) + g(2) = g(3)g(4) - 840
    # g(4) = (g(1) + g(2) + 840) / g(3)
    if (g[1] + g[2] + 840) % g[3] != 0:
        return None
    g[4] = (g[1] + g[2] + 840) // g[3]
    if g[4] <= 1: return None

    for n in range(2, length - 2):
        # g(n) + g(n+1) = g(n+2)g(n+3) - 840
        # g(n+3) = (g(n) + g(n+1) + 840) / g(n+2)
        if (g[n] + g[n+1] + 840) % g[n+2] != 0:
            return None
        g[n+3] = (g[n] + g[n+1] + 840) // g[n+2]
        if g[n+3] <= 1: return None

    return sum(g[1:])

# Let's try some ranges for g1, g2, g3
results = set()
for g1 in range(2, 100):
    for g2 in range(2, 100):
        for g3 in range(2, 100):
            s = check_sequence(g1, g2, g3)
            if s:
                results.add(s)

print(sorted(list(results)))

import math

def is_square(n):
    if n < 0: return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

results_period3 = []
for k in range(1, 10000):
    disc = 5*k*k + 3358*k + 1
    if is_square(disc):
        sqrt_disc = int(math.isqrt(disc))
        for sign in [1, -1]:
            c_num = (k+1) + sign * sqrt_disc
            if c_num % 2 == 0:
                c = c_num // 2
                if c > 1:
                    b = k + c - 1
                    if b > 1:
                        # a = c/k
                        if c % k == 0:
                            a = c // k
                            if a > 1:
                                # Verify with the equations
                                if a+b == c*a - 840 and b+c == a*b - 840 and c+a == b*c - 840:
                                    results_period3.append((a, b, c))

print(results_period3)
